(()=>{
'use strict';
const V='1.0.0-level28-one-tap-final-export-bundle';
const K28='pmp_level28_one_tap_final_export_bundle_v1';
function W(){try{return window.top||window}catch(e){return window}}
function get(k,d){try{return JSON.parse(W().localStorage.getItem(k)||'')||d}catch(e){return d}}
function put(k,v){try{W().localStorage.setItem(k,JSON.stringify(v,null,2))}catch(e){}return v}
function h(s){let x=2166136261;s=String(s||'');for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)}return(x>>>0).toString(16).padStart(8,'0')}
function wins(w,a,n){a=a||[];n=n||0;if(!w||n>8)return a;try{a.push(w);let d=w.document;if(d)d.querySelectorAll('iframe').forEach(f=>{try{if(f.contentWindow)wins(f.contentWindow,a,n+1)}catch(e){}})}catch(e){}return a}
function docs(r,a,n){a=a||[];n=n||0;if(!r||n>8)return a;try{a.push(r);r.querySelectorAll('iframe').forEach(f=>{try{let d=f.contentDocument||(f.contentWindow&&f.contentWindow.document);if(d)docs(d,a,n+1)}catch(e){}})}catch(e){}return a}
function api(n,m){for(const w of wins(W())){let a=w[n];if(a&&typeof a[m||'run']==='function')return a}return null}
async function call(level,n,m){let a=api(n,m||'run');if(!a)throw Error('Level '+level+' API is not loaded');let r=await a[m||'run']();return r}
function status(r){return r&&r.status||'NONE'}
function pass(level,r){let s=status(r);if(level===21)return s==='ONE_TAP_FULL_CHAIN_RETEST_LOCK_PASSED';if(level===22)return s==='EXPORTABLE_CERTIFICATION_RECEIPT_READY';if(level===23)return s==='EXPORT_RECEIPT_INTEGRITY_CHECK_PASSED';if(level===24)return s==='TAMPERED_RECEIPT_REJECTION_TEST_PASSED';if(level===25)return s==='PORTABLE_VERIFICATION_PACKET_READY';if(level===26)return s==='PORTABLE_PACKET_INTEGRITY_CHECK_PASSED';if(level===27)return s==='TAMPERED_PACKET_REJECTION_TEST_PASSED';return false}
function hashOf(r){return r&&(r.retest_hash||r.export_hash||r.integrity_hash||r.rejection_test_hash||r.packet_hash||r.summary_hash)||'none'}
function nm(level){return({21:'One-tap full-chain re-test',22:'Exportable certification receipt',23:'Export receipt integrity check',24:'Tampered receipt rejection test',25:'Portable verification packet',26:'Portable packet integrity check',27:'Tampered packet rejection test'})[level]||('Level '+level)}
async function run(){let steps=[],err=null;async function one(level,n,m){let r=await call(level,n,m);steps.push({level,name:nm(level),status:status(r),passed:pass(level,r),hash:hashOf(r)});return r}let l21,l22,l23,l24,l25,l26,l27;try{l21=await one(21,'PMPOneTapFullChainRetestLockLevel21V1','run');l22=await one(22,'PMPExportableCertificationReceiptLevel22V1','run');l23=await one(23,'PMPExportReceiptIntegrityCheckLevel23V1','runStored');l24=await one(24,'PMPTamperedReceiptRejectionTestLevel24V1','run');l25=await one(25,'PMPPortableVerificationPacketLevel25V1','run');l26=await one(26,'PMPPortablePacketIntegrityCheckLevel26V1','run');l27=await one(27,'PMPTamperedPacketRejectionTestLevel27V1','run')}catch(e){err=e&&e.message||String(e)}let ok=steps.length===7&&steps.every(x=>x.passed)&&!err;let final={type:'PMP_FINAL_EXPORT_BUNDLE',version:V,created_at:new Date().toISOString(),status:ok?'ONE_TAP_FINAL_EXPORT_BUNDLE_READY':'ONE_TAP_FINAL_EXPORT_BUNDLE_FAILED',levels_verified:ok?'27/27':'PARTIAL',source_hash:l25&&l25.source_hash||l26&&l26.source_hash||l21&&l21.source_hash||null,level10_hash:l25&&l25.level10_hash||l26&&l26.level10_hash||l21&&l21.level10_hash||null,level21_retest_hash:l21&&l21.retest_hash||null,level25_packet_hash:l25&&l25.packet_hash||null,level26_integrity_hash:l26&&l26.integrity_hash||null,level27_rejection_hash:l27&&l27.rejection_test_hash||null,steps,packet_text:l25&&l25.packet_text||''};let js=JSON.stringify(final,null,2);final.bundle_hash=h(js);js=JSON.stringify(final,null,2);let text='PMP ONE-TAP FINAL EXPORT BUNDLE\nStatus: '+final.status+'\nLevels verified: '+final.levels_verified+'\nBundle hash: '+final.bundle_hash+'\nSource hash: '+(final.source_hash||'none')+'\nLevel 10 hash: '+(final.level10_hash||'none')+'\nLevel 21 re-test hash: '+(final.level21_retest_hash||'none')+'\nLevel 25 packet hash: '+(final.level25_packet_hash||'none')+'\nLevel 26 integrity hash: '+(final.level26_integrity_hash||'none')+'\nLevel 27 rejection hash: '+(final.level27_rejection_hash||'none')+'\n\nSTEPS\n'+steps.map(s=>'L'+s.level+' '+(s.passed?'PASS':'FAIL')+' — '+s.name+' — '+s.hash).join('\n')+'\n\nJSON\n'+js;let rec={level:28,type:'ONE_TAP_FINAL_EXPORT_BUNDLE',version:V,at:new Date().toISOString(),status:final.status,passed:ok,levels_verified:final.levels_verified,final_export_steps_passed:steps.filter(x=>x.passed).length,final_export_steps_total:7,source_hash:final.source_hash,level10_hash:final.level10_hash,bundle_hash:final.bundle_hash,bundle_char_count:text.length,steps,error:err,bundle_text:text};return put(K28,rec)}
function show(x){if(!x)return'Level 28 ready.';return'Level 28\nStatus: '+(x.status||'NONE')+'\nFinal bundle ready: '+(x.passed?'YES':'NO')+'\nLevels verified: '+(x.levels_verified||'PARTIAL')+'\nFinal export steps: '+(x.final_export_steps_passed||0)+'/'+(x.final_export_steps_total||7)+'\nSource hash: '+(x.source_hash||'none')+'\nLevel 10 hash: '+(x.level10_hash||'none')+'\nBundle hash: '+(x.bundle_hash||'none')+'\nBundle characters: '+(x.bundle_char_count||0)+(x.error?'\nError: '+x.error:'')+'\n\nSteps:\n'+((x.steps||[]).map(s=>'L'+s.level+' '+(s.passed?'PASS':'FAIL')+' — '+s.name+' — '+s.hash).join('\n'))+'\n\nBundle text:\n'+(x.bundle_text||'')}
function sec(){return'<div data-level28-final-export style="margin-top:8px;padding:8px;border-radius:10px;border:1px solid rgba(0,0,0,.08)"><h4 style="margin:0 0 4px">Level 28 — One-Tap Final Export Bundle</h4><p class="sub">Reruns Levels 21–27 and creates one final portable export bundle.</p><div class="grid"><button class="mini" data-l28-run>Run Final Export</button><button class="mini" data-l28-view>View Final Bundle Lock</button></div><pre class="note" data-l28-out style="max-height:520px;overflow:auto;white-space:pre-wrap">Level 28 ready.</pre></div>'}
function patch(d){let root=d.querySelector('[data-source-reference-gate-level4]');if(!root)return;let head=root.querySelector('h4');if(head&&!root.querySelector('[data-l28-badge]'))head.insertAdjacentHTML('afterend','<div data-l28-badge style="margin:4px 0 8px;padding:8px;border-radius:10px;border:2px solid rgba(0,0,0,.18);font-weight:950">Level 28: One-Tap Final Export Bundle — READY</div>');if(!root.querySelector('[data-level28-final-export]'))root.insertAdjacentHTML('beforeend',sec());let out=root.querySelector('[data-l28-out]'),runb=root.querySelector('[data-l28-run]'),vw=root.querySelector('[data-l28-view]');if(runb)runb.onclick=async()=>{out.textContent='Running final export bundle...';try{out.textContent=show(await run())}catch(e){out.textContent='Level 28\nStatus: ROADBLOCK\n'+(e&&e.message||e)}};if(vw)vw.onclick=()=>{out.textContent=show(get(K28,null))}}
function scan(){docs(W().document).forEach(d=>{try{patch(d)}catch(e){}})}
W().PMPOneTapFinalExportBundleLevel28V1={version:V,run,view:()=>get(K28,null),render:show};
window.addEventListener('load',()=>[300,1000,2500,5000].forEach(t=>setTimeout(scan,t)));
setInterval(scan,1000);scan();
})();